<?php require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../includes/functions.php';header('Content-Type: application/json');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['error'=>'Method not allowed']);exit;}$data=json_decode(file_get_contents('php://input'),true);$id=filter_var($data['id']??null,FILTER_VALIDATE_INT);if(!$id){http_response_code(400);echo json_encode(['error'=>'Invalid product']);exit;}$s=$pdo->prepare('SELECT id,stock_quantity FROM products WHERE id=?');$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);echo json_encode(['error'=>'Product not found']);exit;}$_SESSION['cart']=$_SESSION['cart']??[];$n=(int)($_SESSION['cart'][$id]??0);if($n>=(int)$p['stock_quantity']){http_response_code(409);echo json_encode(['error'=>'No more stock available']);exit;}$_SESSION['cart'][$id]=$n+1;echo json_encode(['count'=>cart_count()]);